smart.css:
.smc-root {
  color: var(--smc-text);
  font-family: var(--smc-font-body);
  font-size: 15px;
  line-height: 1.6;
  background-color: var(--smc-bg);
}

.smc-root * {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

.smc-container {
  display: flex;
  flex-direction: column;
  gap: 40px;
  padding: 12px 0;
}

.smc-root.smc-js [data-smc-reveal] {
  opacity: 0;
  transform: translateY(18px);
  transition: opacity 0.5s ease, transform 0.5s ease;
}

.smc-root.smc-js [data-smc-reveal].is-visible {
  opacity: 1;
  transform: translateY(0);
}

.smc-center-title {
  font-family: var(--smc-font-heading);
  font-size: 1.45rem;
  font-weight: 700;
  text-align: center;
  color: var(--smc-text);
  margin-bottom: 8px;
}

.smc-subtitle {
  text-align: center;
  color: var(--smc-muted);
  max-width: 580px;
  margin: 0 auto 24px auto;
  font-size: 0.95rem;
}

/* Hero Intro */
.smc-intro {
  display: grid;
  grid-template-columns: 1fr 340px;
  gap: 28px;
  align-items: center;
  background: linear-gradient(135deg, var(--smc-surface) 0%, color-mix(in srgb, var(--smc-surface) 30%, transparent) 100%);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  padding: 24px;
}

.smc-badge-pill {
  display: inline-block;
  background-color: color-mix(in srgb, var(--smc-primary) 12%, transparent);
  color: var(--smc-primary);
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  padding: 4px 12px;
  border-radius: 999px;
  margin-bottom: 12px;
}

.smc-intro h2 {
  font-family: var(--smc-font-heading);
  font-size: 1.6rem;
  line-height: 1.3;
  font-weight: 700;
  color: var(--smc-text);
  margin-bottom: 12px;
}

.smc-lead {
  font-size: 1rem;
  color: var(--smc-muted);
  margin-bottom: 24px;
}

.smc-metrics {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
  background: var(--smc-bg);
  padding: 14px 12px;
  border-radius: var(--smc-radius);
  border: 1px solid var(--smc-border);
}

.smc-metric-item {
  text-align: center;
  border-right: 1px solid var(--smc-border);
}

.smc-metric-item:last-child {
  border-right: none;
}

.smc-metric-val {
  display: block;
  font-family: var(--smc-font-heading);
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--smc-primary);
}

.smc-metric-label {
  font-size: 0.78rem;
  color: var(--smc-muted);
}

.smc-intro-visual {
  position: relative;
  border-radius: var(--smc-radius);
  overflow: hidden;
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
}

.smc-main-img {
  width: 100%;
  height: auto;
  display: block;
  object-fit: cover;
  cursor: zoom-in;
  transition: transform 0.3s ease;
}

.smc-main-img:hover {
  transform: scale(1.03);
}

/* Feature Cards */
.smc-feature-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
}

.smc-feature-card {
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  padding: 20px;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.smc-feature-card:hover {
  border-color: var(--smc-primary);
  box-shadow: 0 4px 14px color-mix(in srgb, var(--smc-primary) 8%, transparent);
}

.smc-icon-box {
  width: 44px;
  height: 44px;
  border-radius: 8px;
  background-color: var(--smc-surface);
  color: var(--smc-primary);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 14px;
}

.smc-feature-card h3 {
  font-family: var(--smc-font-heading);
  font-size: 1.05rem;
  font-weight: 700;
  margin-bottom: 8px;
  color: var(--smc-text);
}

.smc-feature-card p {
  color: var(--smc-muted);
  font-size: 0.92rem;
  line-height: 1.55;
}

/* Specs Table */
.smc-spec-wrapper {
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  overflow: hidden;
}

.smc-spec-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.95rem;
}

.smc-spec-table tr {
  border-bottom: 1px solid var(--smc-border);
}

.smc-spec-table tr:last-child {
  border-bottom: none;
}

.smc-spec-table tr:nth-child(even) {
  background-color: color-mix(in srgb, var(--smc-surface) 35%, transparent);
}

.smc-spec-table th {
  width: 32%;
  padding: 12px 18px;
  text-align: left;
  font-weight: 600;
  color: var(--smc-text);
  background-color: color-mix(in srgb, var(--smc-surface) 60%, transparent);
  border-right: 1px solid var(--smc-border);
}

.smc-spec-table td {
  padding: 12px 18px;
  color: var(--smc-text);
}

/* Applications */
.smc-apps-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.smc-app-item {
  display: flex;
  align-items: flex-start;
  gap: 16px;
  background: var(--smc-surface);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  padding: 18px;
}

.smc-app-num {
  font-family: var(--smc-font-heading);
  font-size: 1.3rem;
  font-weight: 800;
  color: var(--smc-accent);
  line-height: 1;
  flex-shrink: 0;
  margin-top: 2px;
}

.smc-app-content h4 {
  font-family: var(--smc-font-heading);
  font-size: 1rem;
  font-weight: 700;
  margin-bottom: 6px;
  color: var(--smc-text);
}

.smc-app-content p {
  font-size: 0.9rem;
  color: var(--smc-muted);
  line-height: 1.5;
}

/* Photo Gallery */
.smc-photo-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 20px;
}

.smc-photo-card {
  background: var(--smc-bg);
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.smc-photo-card img {
  width: 100%;
  height: auto;
  display: block;
  cursor: zoom-in;
  transition: transform 0.3s ease;
}

.smc-photo-card img:hover {
  transform: scale(1.02);
}

.smc-photo-card figcaption {
  padding: 12px 14px;
  font-size: 0.85rem;
  text-align: center;
  color: var(--smc-muted);
  background: var(--smc-surface);
  border-top: 1px solid var(--smc-border);
}

/* Responsive container queries */
@container smc (max-width: 720px) {
  .smc-intro {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .smc-metrics {
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
  }

  .smc-metric-item:nth-child(2) {
    border-right: none;
  }

  .smc-metric-item {
    border-bottom: 1px solid var(--smc-border);
    padding-bottom: 8px;
  }

  .smc-metric-item:nth-child(3),
  .smc-metric-item:nth-child(4) {
    border-bottom: none;
    padding-top: 4px;
  }

  .smc-feature-grid,
  .smc-apps-grid,
  .smc-photo-grid {
    grid-template-columns: 1fr;
  }
}

@container smc (max-width: 440px) {
  .smc-spec-table th,
  .smc-spec-table td {
    padding: 10px 12px;
    font-size: 0.88rem;
  }

  .smc-spec-table th {
    width: 38%;
  }

  .smc-center-title {
    font-size: 1.25rem;
  }
}

